//go:build integration

package rpc

import (
 "context"
 "testing"
 "time"
 "github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
)

// BenchmarkLifecycleStages measures cumulative real queue/handler operations.
// It deliberately omits transport encoding and service/executor scheduling.
func BenchmarkLifecycleStages(b *testing.B) {
 for _, budget:=range []bool{false,true} {
  bn:="no_budget";if budget {bn="budget"}
  b.Run(bn,func(b *testing.B){
   for _, stage:=range []string{"context","watch","mutation","read"} {
    b.Run(stage,func(b *testing.B){
     root,stop:=context.WithCancel(context.Background());defer stop()
     sc,stopService:=context.WithCancel(context.Background());defer stopService()
     s:=&Service{ctx:sc,opts:core.ServiceOptions{Timeout:30*time.Second,CancelRunning:stage=="read"},handler:func(context.Context,[]byte)([]byte,error){return nil,nil}}
     e:=&requestEntry{serviceTask:serviceTask{service:s}}
     call:=func(){
      var ctx context.Context;var cancel context.CancelFunc
      if budget {ctx,cancel=context.WithTimeout(root,2*time.Second)} else {ctx,cancel=context.WithCancel(root)}
      e.req.Context=ctx
      if stage!="context" {s.mu.Lock();e.watchQueue(s);e.stopQueueWatch();s.mu.Unlock()}
      if stage=="mutation"||stage=="read" {if err:=s.handle(e.req);err!=nil {b.Fatal(err)}}
      // Actual response dispatch probes Done before inbound tracking finishes.
      select {case <-ctx.Done():b.Fatal("unexpected expiry");default:}
      cancel()
     }
     for i:=0;i<100;i++ {call()}
     b.ReportAllocs();b.ResetTimer()
     for i:=0;i<b.N;i++ {call()}
    })
   }
  })
 }
}

